<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\Overview\Overview; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class OverviewController extends Controller { public function __construct(private Overview $overview) { } public function data(Request $request): JsonResponse { if (!(Addons::get(Addons::ADMIN_OVERVIEW)['enabled'] ?? false)) { throw new NotFoundHttpException(); } $data = $request->validate([ 'range' => ['sometimes', 'string', 'in:' . implode(',', array_keys(Overview::RANGES))], 'nodes' => ['sometimes', 'array', 'max:1000'], 'nodes.*' => ['integer', 'min:1'], ]); $nodes = array_values(array_unique(array_map('intval', $data['nodes'] ?? []))); return new JsonResponse($this->overview->data($data['range'] ?? '24h', $nodes), 200, [ 'Cache-Control' => 'no-store', ]); } } 